KAKAR = [('क्या', 'what'), ('कौन', 'who'), ('कब', 'when'), ('कहाँ', 'where'), ('क्यों', 'why'), ('कैसे', 'how')]


def kakar(r):
    ev = cp('kakar', r, KAKAR_EV)
    city = r.choice(CITIES)
    e = {k: v.format(city=city) for k, v in ev.items()}
    lead = f'{e["when"]} {e["where"]} {e["who"]} {e["why"]} {e["how"]} {e["what"]}।'
    lead = lead[0].upper() + lead[1:]
    kk, key = r.choice(KAKAR)
    wrong = [x for x, _ in KAKAR if x != kk]
    return mcq(f'समाचार का मुखड़ा पढ़िए: "{lead}"\nइसमें "{e[key]}"—यह अंश किस ककार का उत्तर देता है?', kk, r.sample(wrong, 3),
               f'"{e[key]}" "{kk}" का उत्तर है।', r)


def news_write(r):
    ev = cp('news_write', r, KAKAR_EV)
    city = r.choice(CITIES)
    e = {k: v.format(city=city) for k, v in ev.items()}
    stem = (f'निम्नलिखित तथ्यों के आधार पर उलटा पिरामिड शैली में लगभग 80-100 शब्दों का एक समाचार लिखिए और उसे उपयुक्त शीर्षक दीजिए।\n'
            f'तथ्य: कौन—{e["who"].replace(" ने", "")}; क्या—{e["what"]}; कब—{e["when"]}; कहाँ—{e["where"]}; क्यों—{e["why"]}; कैसे—{e["how"]}।')
    return {'stem': stem, 'answer': 'शीर्षक; डेटलाइन; मुखड़े में क्या-कौन-कब-कहाँ; बॉडी में क्यों-कैसे और अन्य विवरण; निष्पक्ष, तथ्यात्मक भाषा।',
            'key': 'अंक-विभाजन (5): शीर्षक और डेटलाइन 1, मुखड़ा (चार ककार) 2, बॉडी (क्यों-कैसे) 1, भाषा 1।', 'marks': 5, 'minutes': 9, 'gap': 'G5'}


